// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 amount, uint8 recipientSeed) public {
        amount = bound(amount, 1, 100 ether);
        address recipient = address(uint160(uint256(keccak256(abi.encode(recipientSeed)))));
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));

        vm.deal(address(c), amount);
        uint256 recipientBalanceBefore = recipient.balance;
        uint256 contractBalanceBefore = address(c).balance;

        c.withdrawAll(recipient);

        uint256 recipientBalanceAfter = recipient.balance;
        assertTrue(recipientBalanceAfter == recipientBalanceBefore + contractBalanceBefore);
    }
}
